import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_dim3_f32(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 D0,
    .param .u32 D1,
    .param .u32 D2,
    .param .u32 reduce_dim,
    .param .u64 out_elems
)
{
    .reg .pred  %p0,%p_exit,%p_case0,%p_case1,%p_done;
    .reg .b32   %r_tid,%r_bid,%r_bdim;
    .reg .b32   %rD0,%rD1,%rD2,%rDim;
     .reg .b64   %in_ptr,%out_ptr,%lin_tid,%out_elems;
    .reg .b64   %uD0,%uD1,%uD2;
    .reg .b64   %S0,%S1,%S2,%base,%step,%R,%k,%tmp0,%tmp1,%tmp2,%addr_elem,%addr_bytes,%out_addr;
    .reg .f32   %val,%max;

    // Load parameters
    ld.param.u64 %in_ptr, [in_ptr];
    ld.param.u64 %out_ptr, [out_ptr];
    ld.param.u32 %rD0, [D0];
    ld.param.u32 %rD1, [D1];
    ld.param.u32 %rD2, [D2];
    ld.param.u32 %rDim, [reduce_dim];
    ld.param.u64 %out_elems, [out_elems];

    // Compute linear thread id
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_bdim, %ntid.x;
    mad.lo.s32 %r_tid, %r_bid, %r_bdim, %r_tid;
     cvt.u64.u32 %lin_tid, %r_tid;

    // Bounds check
     setp.ge.u64 %p_exit, %lin_tid, %out_elems;
    @%p_exit bra EXIT;

    // Convert dims to u64
    cvt.u64.u32 %uD0, %rD0;
    cvt.u64.u32 %uD1, %rD1;
    cvt.u64.u32 %uD2, %rD2;

    // Compute element strides for contiguous [D0,D1,D2]
    // S2 = 1; S1 = D2; S0 = D1*D2
    mov.u64 %S2, 1;
    mov.u64 %S1, 0;
    add.u64 %S1, %S1, %uD2;
    mul.lo.u64 %S0, %uD1, %uD2;

    // Branch by reduce_dim
    setp.eq.u32 %p_case0, %rDim, 0;
    @%p_case0 bra CASE0;
    setp.eq.u32 %p_case1, %rDim, 1;
    @%p_case1 bra CASE1;
    // else case 2
    bra CASE2;

CASE0:
    // Reduce over dim 0, output shape (D1, D2)
    mov.u64 %R, %uD0;                  // R = D0
     div.u64 %tmp0, %lin_tid, %uD2;         // i1 = tid / D2
    mul.lo.u64 %tmp1, %tmp0, %S1;      // i1 * S1
     rem.u64 %tmp2, %lin_tid, %uD2;         // i2 = tid % D2
    add.u64 %base, %tmp1, %tmp2;       // base = i1*S1 + i2
    mov.u64 %step, %S0;                // step = S0
    bra REDUCE;

CASE1:
    // Reduce over dim 1, output shape (D0, D2)
    mov.u64 %R, %uD1;                  // R = D1
     div.u64 %tmp0, %lin_tid, %uD2;         // i0 = tid / D2
    mul.lo.u64 %tmp1, %tmp0, %S0;      // i0 * S0
     rem.u64 %tmp2, %lin_tid, %uD2;         // i2 = tid % D2
    add.u64 %base, %tmp1, %tmp2;       // base = i0*S0 + i2
    mov.u64 %step, %S1;                // step = S1
    bra REDUCE;

CASE2:
    // Reduce over dim 2, output shape (D0, D1)
    mov.u64 %R, %uD2;                  // R = D2
     div.u64 %tmp0, %lin_tid, %uD1;         // i0 = tid / D1
    mul.lo.u64 %tmp1, %tmp0, %S0;      // i0 * S0
     rem.u64 %tmp2, %lin_tid, %uD1;         // i1 = tid % D1
    mul.lo.u64 %tmp2, %tmp2, %S1;      // i1 * S1
    add.u64 %base, %tmp1, %tmp2;       // base = i0*S0 + i1*S1
    mov.u64 %step, %S2;                // step = S2

REDUCE:
    // Initialize with first element
    mov.u64 %k, 0;
    add.u64 %addr_elem, %base, %k;     // addr_elem = base
    shl.b64 %addr_bytes, %addr_elem, 2;
    add.u64 %addr_bytes, %addr_bytes, %in_ptr;
    ld.global.f32 %max, [%addr_bytes];

    // Loop over remaining elements
    mov.u64 %k, 1;
LOOP:
    setp.ge.u64 %p_done, %k, %R;
    @%p_done bra LOOP_END;

    mul.lo.u64 %addr_elem, %k, %step;  // k * step
    add.u64 %addr_elem, %addr_elem, %base;
    shl.b64 %addr_bytes, %addr_elem, 2;
    add.u64 %addr_bytes, %addr_bytes, %in_ptr;
    ld.global.f32 %val, [%addr_bytes];

    setp.gt.f32 %p0, %val, %max;
    @%p0 mov.f32 %max, %val;

    add.u64 %k, %k, 1;
    bra LOOP;

LOOP_END:
    // Store result to out[tid]
     shl.b64 %out_addr, %lin_tid, 2;
    add.u64 %out_addr, %out_addr, %out_ptr;
    st.global.f32 [%out_addr], %max;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_dim3_f32")

