        if not x.is_contiguous():
            raise NotImplementedError("Only contiguous tensors are supported.")

        if rd == 0:
            out_shape = (n1, n2)
        elif rd == 1:
            out_shape = (n0, n2)
        else:
            out_shape = (n0, n1)
        out = torch.empty(out_shape, device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        block = 256
        out_elems = out.numel()
        grid_x = (out_elems + block - 1) // block
        module.launch(
            "max_reduce_dim3_f32",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[x, out, u32(n0), u32(n1), u32(n2), u32(rd), u64(out_elems)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

