    ld.param.u64 %out_ptr, [out_ptr];
    ld.param.u32 %rD0, [D0];
    ld.param.u32 %rD1, [D1];
    ld.param.u32 %rD2, [D2];
    ld.param.u32 %rDim, [reduce_dim];
