    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_bdim, %ntid.x;
    mad.lo.s32 %r_tid, %r_bid, %r_bdim, %r_tid;
     cvt.u64.u32 %lin_tid, %r_tid;

