    mov.u64 %R, %uD1;                  // R = D1
     div.u64 %tmp0, %lin_tid, %uD2;         // i0 = tid / D2
    mul.lo.u64 %tmp1, %tmp0, %S0;      // i0 * S0
     rem.u64 %tmp2, %lin_tid, %uD2;         // i2 = tid % D2
    add.u64 %base, %tmp1, %tmp2;       // base = i0*S0 + i2
    mov.u64 %step, %S1;                // step = S1
    bra REDUCE;

