    mov.u64 %R, %uD2;                  // R = D2
     div.u64 %tmp0, %lin_tid, %uD1;         // i0 = tid / D1
    mul.lo.u64 %tmp1, %tmp0, %S0;      // i0 * S0
     rem.u64 %tmp2, %lin_tid, %uD1;         // i1 = tid % D1
    mul.lo.u64 %tmp2, %tmp2, %S1;      // i1 * S1
